*{box-sizing:border-box} :root{color-scheme:dark;--bg:#10191f;--panel:#172229;--muted:#829198;--text:#eef3ed;--lime:#c8f36a;--line:#2c3a40;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif} html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--sans)}body{min-height:100vh;background-image:radial-gradient(ellipse at 42% 42%,rgba(38,57,62,.36),transparent 58%)}button{font:inherit;color:inherit;cursor:pointer}.game-shell{max-width:1450px;margin:0 auto;padding:0 56px 20px}.topbar{height:74px;border-bottom:1px solid rgba(187,207,199,.13);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:#f2f5ee;text-decoration:none;font-size:13px;font-weight:800;letter-spacing:2.1px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border:1px solid var(--lime);border-radius:8px;color:var(--lime);font-size:16px;letter-spacing:0;font-weight:700}.brand-light{color:#8e9b9b;font-weight:500}.top-meta{font:10px var(--mono);letter-spacing:1.55px;color:#91a19e;display:flex;gap:9px;align-items:center}.live-dot,.dash-state i,.footer-dot{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px rgba(200,243,106,.55)}.sound-button{background:none;border:0;color:#a8b6b2;font:11px var(--mono);letter-spacing:1px;padding:10px}.sound-button span{font-size:9px;margin-left:4px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 268px;gap:25px;padding-top:30px}.game-main{min-width:0}.mission-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:21px}.eyebrow,.dash-label,.stat-label,.speed-label,.objective-label{font:10px var(--mono);letter-spacing:1.45px;color:#9aa8a6}.eyebrow{display:flex;align-items:center;gap:9px;color:var(--lime)}.eyebrow-line{height:1px;width:21px;background:var(--lime)}h1{font-size:31px;line-height:1.2;letter-spacing:-1.3px;margin:9px 0 4px;font-weight:700}h1 em{font-style:normal;color:var(--lime)}.subtitle{font-size:12px;color:#a0aeac;margin:0}.level-chip{display:flex;align-items:center;gap:8px;padding:8px 11px;border:1px solid #35454a;border-radius:5px;font:10px var(--mono);letter-spacing:1px;color:#889895;margin-bottom:3px}.level-chip strong{font:600 16px var(--mono);color:var(--lime)}.level-total{color:#60716f}.scene-wrap{position:relative;width:100%;aspect-ratio:1.55;background:#293735;border:1px solid #40504d;overflow:hidden;border-radius:7px;box-shadow:0 14px 40px rgba(0,0,0,.2)}canvas{display:block;width:100%;height:100%;touch-action:none}.scene-label{position:absolute;left:15px;top:14px;padding:8px 10px;border-radius:3px;background:rgba(15,24,27,.82);font:9px var(--mono);letter-spacing:1px;color:#d4ded7;pointer-events:none}.map-pin{font-size:13px;color:var(--lime);margin-right:5px}.label-divider{color:#6c7d78;padding:0 5px}.scene-hint{position:absolute;right:13px;top:14px;display:flex;align-items:center;gap:4px;color:#d0d9d3;font:9px var(--mono);letter-spacing:1px;padding:6px 8px;background:rgba(15,24,27,.76);border-radius:3px;transition:opacity .4s;pointer-events:none}.scene-hint.hidden{opacity:0}.hint-key{display:inline-grid;place-items:center;width:16px;height:16px;border:1px solid #52615c;border-radius:3px;font-size:9px;color:var(--lime)}.toast{position:absolute;left:50%;bottom:18px;transform:translate(-50%,8px);padding:9px 14px;background:rgba(17,26,28,.94);border:1px solid rgba(200,243,106,.4);border-radius:4px;color:var(--lime);font:10px var(--mono);letter-spacing:.8px;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.level-complete{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:rgba(14,22,23,.84);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.3s}.level-complete.show{opacity:1;visibility:visible}.complete-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:rgba(200,243,106,.15);border:1px solid var(--lime);color:var(--lime);font-size:22px;margin-bottom:13px}.complete-kicker{font:10px var(--mono);letter-spacing:2px;color:var(--lime)}.level-complete h2{font-size:24px;letter-spacing:-.7px;margin:7px 0}.level-complete p{font-size:12px;color:#b1bfba;margin:0 0 17px}.primary-button{background:var(--lime);color:#18211c;border:0;border-radius:4px;padding:11px 16px;font:700 10px var(--mono);letter-spacing:1px}.primary-button span{font-size:15px;margin-left:14px}.bottom-bar{height:65px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(187,207,199,.13)}.objective{display:flex;align-items:center;gap:10px}.objective-icon{font-size:25px;color:var(--lime)}.objective-label{display:block;font-size:8px;color:#7f918c;margin-bottom:3px}.objective strong{font-size:11px;font-weight:600;color:#dce4dd}.bottom-actions{display:flex;align-items:center;gap:15px}.text-button{background:none;border:0;color:#a6b3ae;font:9px var(--mono);letter-spacing:1px;padding:8px}.restart-icon{font-size:16px;vertical-align:-1px;margin-right:4px}.pause-button{height:30px;width:30px;background:transparent;border:1px solid #3b4a4b;border-radius:4px;color:#c5cfca;font-size:13px}.dashboard{background:linear-gradient(150deg,#1b282e,#172228 70%);border:1px solid #2b3a40;border-radius:6px;min-height:500px;padding:18px 17px 13px;display:flex;flex-direction:column}.dash-top{display:flex;justify-content:space-between;align-items:center}.dash-label{font-size:9px}.dash-state{font:9px var(--mono);letter-spacing:.7px;color:var(--lime);display:flex;align-items:center;gap:7px}.dash-state i{width:5px;height:5px}.speed-panel{margin-top:24px;padding-bottom:15px;border-bottom:1px solid #2e3b40}.speed-label{font-size:8px;letter-spacing:1.2px;color:#84938f}.speed-label span{float:right;color:#5f706d}.speed-reading{margin-top:7px;display:flex;align-items:baseline;gap:8px}.speed-reading>span:first-child{font:400 49px/.95 var(--mono);letter-spacing:-4px;color:#f0f3ed}.speed-unit{font:9px var(--mono);letter-spacing:.8px;color:#8c9a95}.speed-track{height:4px;position:relative;background:#354448;margin-top:12px;border-radius:3px;display:flex;justify-content:space-between}.speed-track span{position:relative;top:-2px;height:8px;width:1px;background:#62706a}.speed-track div{position:absolute;height:4px;width:0;left:0;top:0;background:var(--lime);border-radius:4px;transition:width .12s}.gear-row{display:flex;align-items:center;gap:9px;margin-top:15px}.gear-row>span:first-child{font:9px var(--mono);letter-spacing:1px;color:#7e8d89}.gear-row strong{font:600 12px var(--mono);color:var(--lime);border:1px solid #45544e;border-radius:3px;width:22px;height:22px;display:grid;place-items:center}.gear-caption{font:8px var(--mono);letter-spacing:.8px;color:#788982}.dash-stats{display:grid;grid-template-columns:1fr 1fr;padding:16px 0}.stat-box+.stat-box{border-left:1px solid #344247;padding-left:17px}.stat-label{display:block;font-size:8px;margin-bottom:6px;color:#84918d}.stat-box strong{font:14px var(--mono);color:#e8eee8}.bump-limit{font-size:9px;color:#71817d}.divider{height:1px;background:#2e3b40}.guide-head{display:flex;align-items:center;gap:8px;margin:16px 0 10px;font:9px var(--mono);letter-spacing:1.2px;color:#ccd5ce}.guide-icon{font-size:16px;color:var(--lime)}.key-guide{display:flex;flex-direction:column;gap:7px}.key-row{display:grid;grid-template-columns:33px 1fr 23px;align-items:center;gap:8px;font-size:10px;color:#9ca9a4}.keycap{height:21px;min-width:22px;display:grid;place-items:center;background:#202e34;border:1px solid #3a494e;border-bottom-width:2px;border-radius:4px;color:#dbe4dc;font:10px var(--mono)}.keycap.wide{width:31px}.keycap:not(.wide){justify-self:end}.key-row:last-child{grid-template-columns:58px 1fr;margin-top:2px}.key-row:last-child .keycap{width:54px;font-size:8px}.tip-card{margin-top:auto;display:flex;gap:10px;background:#202d2b;border:1px solid #33443d;border-radius:4px;padding:11px 10px}.tip-spark{color:var(--lime);font-size:15px}.tip-card strong{font:9px var(--mono);letter-spacing:.8px;color:#dce9d5}.tip-card p{font-size:9px;line-height:1.55;color:#96a49e;margin:5px 0 0}.dash-footer{font:7px var(--mono);letter-spacing:.8px;color:#6d7f79;display:flex;align-items:center;gap:6px;margin-top:13px}.footer-dot{width:5px;height:5px}.page-footer{display:flex;justify-content:space-between;padding-top:17px;color:#62726f;font:8px var(--mono);letter-spacing:1px}.page-footer b{color:var(--lime);font-size:12px;margin-left:4px}.mobile-controls{display:none}
@media(max-width:1000px){.game-shell{padding:0 25px 20px}.game-layout{grid-template-columns:minmax(0,1fr) 235px;gap:16px}.dashboard{padding:15px 13px}.speed-reading>span:first-child{font-size:42px}}
@media(max-width:760px){.game-shell{padding:0 16px 22px}.topbar{height:58px}.top-meta{font-size:8px;letter-spacing:1px}.sound-button{padding-right:0}.game-layout{display:flex;flex-direction:column;padding-top:23px;gap:13px}.mission-head{margin-bottom:15px}h1{font-size:26px}.subtitle{font-size:11px}.level-chip{font-size:9px;padding:7px}.scene-wrap{aspect-ratio:1.16;border-radius:5px}.scene-label{left:8px;top:8px;padding:6px;font-size:7px}.scene-hint{right:7px;top:8px;padding:4px;gap:2px;font-size:7px}.hint-key{height:13px;width:13px;font-size:7px}.dashboard{min-height:unset;display:grid;grid-template-columns:1fr 1fr;column-gap:13px;padding:12px 13px}.dash-top{grid-column:1/-1}.speed-panel{margin-top:13px;grid-row:2/4;padding:0;border:0}.speed-reading>span:first-child{font-size:38px}.speed-track{margin-top:8px}.gear-row{margin-top:9px}.dash-stats{padding:11px 0 8px;grid-column:2;grid-row:2}.stat-box+.stat-box{padding-left:10px}.guide-head,.key-guide,.tip-card,.dash-footer{display:none}.dashboard .divider{display:none}.bottom-bar{height:58px}.objective strong{font-size:10px}.text-button{font-size:8px;padding:6px}.bottom-actions{gap:5px}.page-footer{font-size:7px;padding-top:13px}.mobile-controls{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;padding:12px 3px calc(7px + env(safe-area-inset-bottom))}.steer-controls,.pedal-controls{display:flex;gap:8px}.mobile-controls button{border:1px solid #42534d;background:#1a282b;border-radius:9px;color:#e5eee4;touch-action:none;user-select:none;-webkit-user-select:none}.steer-controls button{height:53px;width:55px;font-size:22px}.pedal-controls button{height:53px;width:58px;font:10px var(--mono);letter-spacing:1px}.pedal-controls .forward-control{background:#c8f36a;color:#1b251e;border-color:#c8f36a}.mobile-brake{height:40px;padding:0 12px;font:9px var(--mono)!important;color:#ffb6a4!important}.mobile-controls button:active,.mobile-controls button.active{transform:translateY(2px);filter:brightness(1.25)}.toast{bottom:8px;font-size:8px}.level-complete h2{font-size:20px}}
@media(max-width:390px){.top-meta{display:none}.scene-wrap{aspect-ratio:1.07}.mobile-controls{gap:6px}.steer-controls,.pedal-controls{gap:5px}.steer-controls button{height:48px;width:48px}.pedal-controls button{height:48px;width:51px}.mobile-brake{padding:0 8px}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const ui = {
    level: document.getElementById('levelNumber'), speed: document.getElementById('speedValue'),
    speedFill: document.getElementById('speedFill'), gear: document.getElementById('gearValue'),
    gearCaption: document.getElementById('gearCaption'), time: document.getElementById('timeValue'),
    bumps: document.getElementById('bumpValue'), status: document.getElementById('statusText'),
    toast: document.getElementById('toast'), hint: document.getElementById('sceneHint'),
    complete: document.getElementById('levelComplete'), completeText: document.getElementById('completeText'),
    next: document.getElementById('nextButton'), restart: document.getElementById('restartButton'),
    pause: document.getElementById('pauseButton'), sound: document.getElementById('soundButton')
  };
  const W = 960, H = 620;
  const keys = new Set();
  const levels = [
    { target: 760, title: 'THE EASY ONE', car: 'mint', text: 'A perfect first park. Smooth and steady.' },
    { target: 540, title: 'TIGHT FIT', car: 'blue', text: 'Nice work. That one took a little more finesse.' },
    { target: 320, title: 'HOME STRETCH', car: 'orange', text: 'Three for three. You make it look easy.' }
  ];
  const palette = ['#d7e5d7','#d7e5d7','#d7e5d7','#d7e5d7','#d7e5d7','#d7e5d7','#d7e5d7','#d7e5d7','#d7e5d7'];
  let levelIndex = 0, player, obstacles, cones, elapsed = 0, bumps = 0, completed = false, paused = false;
  let lastTime = performance.now(), toastTimer = 0, parkingProgress = 0, soundOn = false;
  let audioContext;

  function setCanvasSize() {
    const rect = canvas.getBoundingClientRect();
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(rect.width * ratio);
    canvas.height = Math.round(rect.height * ratio);
    ctx.setTransform(canvas.width / W, 0, 0, canvas.height / H, 0, 0);
  }
  new ResizeObserver(setCanvasSize).observe(canvas);
  window.addEventListener('resize', setCanvasSize);

  function setupLevel(resetBumps = false) {
    const spec = levels[levelIndex];
    if (resetBumps) bumps = 0;
    player = { x: 122, y: 322, angle: 0, v: 0, steer: 0, bumpFlash: 0 };
    obstacles = [];
    const upperX = [155, 265, 375, 485, 595, 705, 815, 905];
    upperX.forEach((x, i) => obstacles.push({ x, y: 123, angle: Math.PI / 2, color: ['#9ca8a1','#d5a77d','#82959e','#c5c6b5'][i % 4] }));
    const lowerX = [155, 265, 375, 485, 595, 705, 815, 905];
    lowerX.forEach((x, i) => {
      if (Math.abs(x - spec.target) < 3) return;
      obstacles.push({ x, y: 487, angle: Math.PI / 2, color: ['#a8b8b0','#d3c7b1','#849a9b','#b88e7e'][i % 4] });
    });
    // A few parked cars sit on the far edge of the lot, away from the driving lane.
    obstacles.push({ x: 72, y: 123, angle: Math.PI / 2, color: '#b7c1af' });
    cones = [{x:915,y:365},{x:915,y:410},{x:76,y:365},{x:76,y:410}];
    elapsed = 0; parkingProgress = 0; completed = false; paused = false;
    ui.level.textContent = String(levelIndex + 1).padStart(2, '0');
    ui.complete.classList.remove('show');
    ui.pause.textContent = 'Ⅱ';
    updateDashboard();
    showToast(spec.title, 1500);
  }

  function showToast(message, duration = 1100) {
    ui.toast.textContent = message;
    ui.toast.classList.add('show');
    toastTimer = duration;
  }
  function updateDashboard() {
    const kmh = Math.round(Math.abs(player.v) * .34);
    ui.speed.textContent = String(kmh).padStart(2, '0');
    ui.speedFill.style.width = `${Math.min(kmh / 55 * 100, 100)}%`;
    ui.gear.textContent = Math.abs(player.v) < 2 ? 'P' : player.v < 0 ? 'R' : 'D';
    ui.gearCaption.textContent = Math.abs(player.v) < 2 ? 'PARKED' : player.v < 0 ? 'REVERSE' : 'DRIVE';
    const minutes = Math.floor(elapsed / 60), seconds = Math.floor(elapsed % 60);
    ui.time.textContent = `${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
    ui.bumps.innerHTML = `${bumps}<span class="bump-limit"> / 3</span>`;
    ui.status.textContent = completed ? 'COMPLETE' : paused ? 'PAUSED' : Math.abs(player.v) < 1 ? 'READY' : 'IN MOTION';
    ui.status.style.color = bumps >= 3 ? '#ff9d87' : '';
  }

  function roundedRect(x, y, w, h, r, fill, stroke) {
    ctx.beginPath(); ctx.roundRect(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.stroke(); }
  }
  function drawBackground() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#263331'; ctx.fillRect(0, 0, W, H);
    // Subtle asphalt grain.
    for (let i=0;i<165;i++) {
      const x = (i * 197 + 31) % W, y = (i * 113 + 17) % H;
      ctx.fillStyle = i % 3 ? 'rgba(204,214,188,.025)' : 'rgba(5,12,10,.07)';
      ctx.fillRect(x, y, 1 + (i % 2), 1);
    }
    // Lot perimeter and planted edges.
    roundedRect(28, 29, 904, 562, 20, '#303e3a', '#52615a');
    roundedRect(47, 47, 866, 526, 13, '#3a4541', null);
    ctx.fillStyle = '#303d39'; ctx.fillRect(49, 48, 862, 30); ctx.fillRect(49, 559, 862, 14);
    for (let x=74; x<900; x+=46) {
      roundedRect(x, 53, 26, 19, 8, x%3 ? '#526557' : '#60705a', null);
      ctx.fillStyle='rgba(190,205,151,.17)';ctx.beginPath();ctx.arc(x+10,59,3,0,Math.PI*2);ctx.fill();
    }
    // Parking bays in the top and bottom rows.
    ctx.strokeStyle='rgba(225,229,205,.34)';ctx.lineWidth=1.4;ctx.setLineDash([]);
    const slots=[100,210,320,430,540,650,760,870];
    slots.forEach(x=>{ctx.beginPath();ctx.moveTo(x,79);ctx.lineTo(x,170);ctx.stroke();ctx.beginPath();ctx.moveTo(x,438);ctx.lineTo(x,559);ctx.stroke();});
    ctx.beginPath();ctx.moveTo(50,170);ctx.lineTo(910,170);ctx.stroke();
    ctx.beginPath();ctx.moveTo(50,438);ctx.lineTo(910,438);ctx.stroke();
    // Main travel lane with center dashes.
    ctx.fillStyle='#414b46';ctx.fillRect(50,185,860,235);
    ctx.strokeStyle='rgba(218,222,198,.22)';ctx.setLineDash([17,16]);ctx.lineWidth=1.5;
    ctx.beginPath();ctx.moveTo(74,303);ctx.lineTo(886,303);ctx.stroke();ctx.setLineDash([]);
    // Entrance arrows and pedestrian walk.
    ctx.fillStyle='rgba(227,232,210,.43)';
    for(let i=0;i<5;i++)ctx.fillRect(88+i*9,260,5,39);
    ctx.save();ctx.translate(98,356);ctx.rotate(-Math.PI/2);ctx.fillStyle='rgba(214,221,202,.6)';ctx.font='10px monospace';ctx.fillText('IN',0,0);ctx.restore();
    // Bay target, softly pulsing.
    const target=levels[levelIndex].target;
    const pulse=.10+Math.sin(performance.now()/270)*.04;
    ctx.fillStyle=`rgba(200,243,106,${pulse})`;ctx.fillRect(target-39,439,78,118);
    ctx.strokeStyle='rgba(200,243,106,.85)';ctx.lineWidth=2;ctx.setLineDash([6,5]);ctx.strokeRect(target-39,439,78,118);ctx.setLineDash([]);
    // Bay mouth chevron, points into the space.
    ctx.strokeStyle='rgba(200,243,106,.75)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(target-10,430);ctx.lineTo(target,439);ctx.lineTo(target+10,430);ctx.stroke();
    ctx.fillStyle='rgba(200,243,106,.84)';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('PARK HERE',target,548);ctx.textAlign='left';
    // Small lamps and lot signage.
    for(const x of [180,480,780]) {ctx.fillStyle='rgba(224,229,195,.45)';ctx.beginPath();ctx.arc(x,200,2,0,Math.PI*2);ctx.fill();}
  }

  function drawCar(car, isPlayer=false) {
    ctx.save();ctx.translate(car.x,car.y);ctx.rotate(car.angle);
    const L=isPlayer?47:44, B=isPlayer?24:23;
    // Soft shadow.
    ctx.fillStyle='rgba(0,0,0,.32)';roundedRect(-L/2+2,-B/2+4,L,B,7,ctx.fillStyle,null);
    let body;
    if(isPlayer) body='#c8f36a'; else body=car.color;
    if(isPlayer && car.bumpFlash>0) body=(Math.floor(car.bumpFlash*16)%2)?'#ff927d':'#c8f36a';
    roundedRect(-L/2,-B/2,L,B,7,body,null);
    // Hood / trunk and side sill detail.
    roundedRect(L*.16,-B*.37,L*.25,B*.74,4,isPlayer?'#ddffa0':'rgba(255,255,255,.21)',null);
    roundedRect(-L*.34,-B*.34,L*.19,B*.68,3,isPlayer?'#9cc94e':'rgba(30,40,39,.2)',null);
    // Panoramic windows.
    roundedRect(-L*.12,-B*.34,L*.29,B*.68,4,isPlayer?'#344d47':'#35464a',null);
    ctx.fillStyle='rgba(226,240,224,.22)';ctx.fillRect(-L*.05,-B*.29,2,B*.58);
    // Wheels.
    ctx.fillStyle='#18201f';
    for(const wx of [-L*.28,L*.26])for(const wy of [-B*.49,B*.49])roundedRect(wx-5,wy-2.5,10,5,2,'#19211f',null);
    // Headlights / tail lights.
    ctx.fillStyle=isPlayer?'#fff3bd':'#f1e7c6';roundedRect(L/2-3,-B*.31,2,4,1,ctx.fillStyle,null);roundedRect(L/2-3,B*.13,2,4,1,ctx.fillStyle,null);
    ctx.fillStyle='#fa715e';roundedRect(-L/2,-B*.31,2,4,1,ctx.fillStyle,null);roundedRect(-L/2,B*.13,2,4,1,ctx.fillStyle,null);
    if(isPlayer){ctx.fillStyle='rgba(244,255,198,.65)';ctx.beginPath();ctx.moveTo(L/2, -B*.2);ctx.lineTo(L/2+27,-B*.8);ctx.lineTo(L/2+27,B*.8);ctx.lineTo(L/2,B*.2);ctx.closePath();ctx.fill();}
    ctx.restore();
  }
  function drawCone(cone) {
    ctx.fillStyle='rgba(0,0,0,.28)';ctx.beginPath();ctx.ellipse(cone.x+2,cone.y+6,10,6,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ef835f';ctx.beginPath();ctx.moveTo(cone.x,cone.y-9);ctx.lineTo(cone.x+8,cone.y+7);ctx.lineTo(cone.x-8,cone.y+7);ctx.closePath();ctx.fill();
    ctx.strokeStyle='#f7d8b8';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cone.x-5,cone.y+1);ctx.lineTo(cone.x+5,cone.y+1);ctx.stroke();
  }
  function render() {
    drawBackground();
    obstacles.forEach(o=>drawCar(o));cones.forEach(drawCone);
    if(player)drawCar(player,true);
    if(paused&&!completed){ctx.fillStyle='rgba(12,20,20,.62)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#c8f36a';ctx.textAlign='center';ctx.font='bold 17px Manrope';ctx.fillText('PAUSED',W/2,H/2-3);ctx.fillStyle='#d3ddd4';ctx.font='10px monospace';ctx.fillText('PRESS SPACE OR TAP II TO RESUME',W/2,H/2+20);ctx.textAlign='left';}
  }

  function carCorners(car) {
    const c=Math.cos(car.angle), s=Math.sin(car.angle), L=22.5, B=11.5;
    return [[-L,-B],[L,-B],[L,B],[-L,B]].map(([x,y])=>[car.x+x*c-y*s,car.y+x*s+y*c]);
  }
  function polygonsOverlap(a,b) {
    for(const poly of [a,b]) for(let i=0;i<poly.length;i++) {
      const p1=poly[i],p2=poly[(i+1)%poly.length], axis=[-(p2[1]-p1[1]),p2[0]-p1[0]];
      let amin=Infinity,amax=-Infinity,bmin=Infinity,bmax=-Infinity;
      for(const p of a){const d=p[0]*axis[0]+p[1]*axis[1];amin=Math.min(amin,d);amax=Math.max(amax,d);}
      for(const p of b){const d=p[0]*axis[0]+p[1]*axis[1];bmin=Math.min(bmin,d);bmax=Math.max(bmax,d);}
      if(amax < bmin || bmax < amin)return false;
    }
    return true;
  }
  function hasCollision() {
    const poly=carCorners(player);
    if(poly.some(([x,y])=>x<49||x>911||y<79||y>558))return true;
    for(const car of obstacles) if(polygonsOverlap(poly,carCorners(car)))return true;
    for(const cone of cones) if(Math.hypot(player.x-cone.x,player.y-cone.y)<22)return true;
    return false;
  }
  function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b));}
  function parkCheck(dt) {
    const target=levels[levelIndex].target;
    const centered=Math.abs(player.x-target)<17&&Math.abs(player.y-488)<26;
    const aligned=Math.abs(angleDiff(player.angle,Math.PI/2))<.24;
    if(centered&&aligned&&Math.abs(player.v)<14){
      parkingProgress+=dt;
      ui.status.textContent='HOLD STEADY';
      if(parkingProgress>.85) finishLevel();
    } else parkingProgress=Math.max(0,parkingProgress-dt*1.7);
  }
  function finishLevel() {
    if(completed)return;
    completed=true;player.v=0;
    const score=Math.max(0,100-Math.round(elapsed*1.4)-bumps*12);
    ui.completeText.textContent=`${levels[levelIndex].text}  •  ${score}% parking score`;
    ui.next.innerHTML=levelIndex===levels.length-1?'PLAY AGAIN <span>↻</span>':'NEXT LEVEL <span>→</span>';
    ui.complete.classList.add('show');
    updateDashboard();playTone(660,.12);setTimeout(()=>playTone(880,.16),120);
  }
  function playTone(freq,duration=.08) {
    if(!soundOn)return;
    try{audioContext??=new AudioContext();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.frequency.value=freq;osc.type='sine';gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+duration);}catch{}
  }
  function inputDown(name){return keys.has(name);}
  function update(dt) {
    if(!paused&&!completed) {
      elapsed+=dt;
      const forward=inputDown('w')||inputDown('arrowup')||inputDown('forward');
      const reverse=inputDown('s')||inputDown('arrowdown')||inputDown('reverse');
      const left=inputDown('a')||inputDown('arrowleft')||inputDown('left');
      const right=inputDown('d')||inputDown('arrowright')||inputDown('right');
      const brake=inputDown(' ')||inputDown('brake');
      const oldX=player.x,oldY=player.y,oldAngle=player.angle;
      const throttle=(forward?1:0)-(reverse?1:0);
      if(throttle) player.v+=throttle*124*dt;
      else player.v*=Math.pow(.985,dt*60);
      if(brake)player.v*=Math.pow(.88,dt*60);
      player.v=Math.max(-74,Math.min(153,player.v));
      const steer=((right?1:0)-(left?1:0));
      const steerAmount=Math.min(Math.abs(player.v)/52,1);
      player.angle+=steer*steerAmount*1.82*dt*(player.v<0?-1:1);
      player.x+=Math.cos(player.angle)*player.v*dt;
      player.y+=Math.sin(player.angle)*player.v*dt;
      player.bumpFlash=Math.max(0,player.bumpFlash-dt);
      if(hasCollision()) {
        player.x=oldX;player.y=oldY;player.angle=oldAngle;player.v=0;player.bumpFlash=.5;
        bumps++;playTone(130,.1);
        showToast(bumps>=3?'OOPS — TRY AGAIN':'BUMP! TAKE IT SLOW',1200);
        if(bumps>=3){setTimeout(()=>{if(bumps>=3){bumps=0;setupLevel(false);showToast('FRESH START — YOU GOT THIS',1500);}},950);}
      } else parkCheck(dt);
      if(Math.abs(player.v)>3)ui.hint.classList.add('hidden');
    }
    if(toastTimer>0){toastTimer-=dt*1000;if(toastTimer<=0)ui.toast.classList.remove('show');}
    updateDashboard();render();
  }
  function loop(now){const dt=Math.min((now-lastTime)/1000,.035);lastTime=now;update(dt);requestAnimationFrame(loop);}

  window.addEventListener('keydown',e=>{
    const key=e.key.toLowerCase();
    if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();
    keys.add(key);
    if(key===' '&&!e.repeat&&paused)togglePause();
    if(key==='r'&&!e.repeat)setupLevel(true);
    if((key==='escape'||key==='p')&&!e.repeat)togglePause();
  });
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  window.addEventListener('blur',()=>keys.clear());
  document.querySelectorAll('[data-control]').forEach(button=>{
    const name=button.dataset.control;
    const down=e=>{e.preventDefault();keys.add(name);button.classList.add('active');try{button.setPointerCapture(e.pointerId);}catch{}};
    const up=e=>{e.preventDefault();keys.delete(name);button.classList.remove('active');};
    button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up);
  });
  function togglePause(){if(completed)return;paused=!paused;ui.pause.textContent=paused?'▶':'Ⅱ';updateDashboard();}
  ui.restart.addEventListener('click',()=>setupLevel(true));
  ui.pause.addEventListener('click',togglePause);
  ui.next.addEventListener('click',()=>{levelIndex=(levelIndex+1)%levels.length;setupLevel(true);});
  ui.sound.addEventListener('click',()=>{soundOn=!soundOn;ui.sound.classList.toggle('sound-on',soundOn);ui.sound.innerHTML=`${soundOn?'♫':'♫'} <span>${soundOn?'ON':'SOUND'}</span>`;if(soundOn)playTone(520,.08);});
  // Avoid stuck keys when the page loses focus or is switched in the browser.
  document.addEventListener('visibilitychange',()=>{if(document.hidden)keys.clear();});
  setupLevel(true);setCanvasSize();requestAnimationFrame(loop);
})();

